import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, Output } from '@angular/core';
import { ButtonComponent } from '../button/button.component';
import { IconComponent } from '../icon/icon.component';
import { MatDialog, MatDialogModule } from '@angular/material/dialog';
import { ImageviewerComponent } from '../imageviewer/imageviewer.component';
import { TicketService } from '../../services/ticket/ticket.service';
import { tickerList } from '../../interfaces/ticket.interface';
import { MatMenuModule } from '@angular/material/menu';
import { Subject } from 'rxjs';
import { ActivatedRoute } from '@angular/router';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';
import { environment } from '../../../../environments/environment';

@Component({
  selector: 'app-tickets',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [CommonModule, ButtonComponent, IconComponent, MatDialogModule, MatMenuModule],
  templateUrl: './tickets.component.html',
  styleUrl: './tickets.component.scss'
})
export class TicketsComponent {
  @Output() ticketClose: EventEmitter<string> = new EventEmitter();
  @Output() ticketCleard: EventEmitter<number> = new EventEmitter();

  @Input() onTickets: Subject<number>;
  @Input() nTicketCaseId: string = null;
  ticketList: tickerList[] = [];
  isAdmin: boolean = false;
  imageURL = `${environment.documentStorage}${environment.ticketPath}`;
  constructor(private dialog: MatDialog, private ts: TicketService, private cd: ChangeDetectorRef, private route: ActivatedRoute, private cf: CommonfunctionService) {

  }

  ngOnInit() {
    if (this.onTickets) {

      this.fetchList();
      this.onTickets.subscribe((caseid: any) => {
        this.ticketList = [];
        this.nTicketCaseId = caseid;
        this.fetchList();
      })
    } else {
      this.isAdmin = true;
      var params = this.route.snapshot.params;
      params = JSON.parse(atob(params["id"]));
      this.nTicketCaseId = params && params["id"] ? params["id"] : 0;
      if (this.nTicketCaseId) {
        this.fetchAllTicketsList()
      }
    }

  }

  async fetchAllTicketsList(): Promise<void> {
    this.ticketList = await this.ts.getAllTicketList(this.nTicketCaseId);
    this.cd.detectChanges();
  }

  async fetchList() {
    this.ticketList = await this.ts.getTicketList(this.nTicketCaseId);
    this.cd.detectChanges();
  }

  async resolved(nTicketid: string) {
    let rs = await this.ts.resolveTicket(nTicketid);
    if (rs) {
      let tkt: tickerList = this.ticketList.find(a => a.nTicketid == nTicketid);
      tkt.cStatus = 'C';
      this.cd.detectChanges();

    }
  }

  async clearAll() {
    let rs;
    if (this.isAdmin)
      rs = await this.ts.clearAllResolvedTicketsAsAdmin(this.nTicketCaseId);
    else
      rs = await this.ts.clearAllResolvedTickets(this.nTicketCaseId);

    if (rs) {
      this.ticketList = this.ticketList.filter(a => a.cStatus == 'P')
      this.cd.detectChanges();

      this.ticketCleard.emit(this.ticketList.length);
    }

  }

  viewImage(x) {
    const dialogRef = this.dialog.open(ImageviewerComponent, {
      maxHeight: '95vh',
      data: {
        cPath: `${this.imageURL}${x.cImgpath}`,
      },
    });
  }


  close() {
    if (this.isAdmin) {
      this.cf.goto('/admin/dashboard')
      return;
    }
    this.ticketClose.emit('CLOSE')
  }

}
